// =====================================================================
// A-ASYA-0078 — 1923 A KATMANI: YUNNAN GB · PAMİR · BORNEO · TİMOR · SAHALİN NOKTALARI
// (24 Eylül 2026 · şartname oturumlar/BITIR-1923-0078.md §3.2 · koordinatör YILDIRIM BAYEZIT)
//
// AD ALANI (§7): data/yerlesimler_a78_asya.js → window.YERLESIMLER_A78_ASYA
// 🔴 arac/girdi.py GIRDI_DOSYALARI'na BAĞLI DEĞİL — koordinatör ekler.
//
// ÜRETİLİR, ELLE YAZILMAZ: py denetim/A-ASYA-0078-uret.py --yaz
//   girdi  denetim/A-ASYA-0078-noktalar.json · ölçü denetim/A-ASYA-0078-olc.py
//   sınav  künye var mı · künye penceresi · renk · ters/sıfır/çakışma · kesintisizlik
//          (kur|1281 → 1923-10-29) · her dönemde kaynak · ad (norm) · 3 km
//
// NİÇİN: 1923-09-01'de son üretimde bu kutuların kara hücrelerinin GÖVDESİZ oranı
// Yunnan-GB %60,7 · Pamir %95,4 · Borneo %53,1 · Timor %27,4 · Sahalin %42,0.
//
// 🟡 __BOSLUK__ = künyesi olmayan yerel yönetim (Şugnan/Vahan mîrleri, Sintang, Yettişar,
//   Pingnan kalıntısı 1873) — komşu künyeye İTİLMEDİ. tur:"bolge" = dolgu noktası, yerleşim
//   iddiası taşımaz (kuruluş günü bulunamayan kıyı/iç bölgeler).
